import itertools
base={'1':np.ones(300),'P':P,'P2':P**2,'P3':P**3,'t':t,'tP':t*P,'t2':t**2,'t3':t**3,'1/P':1/P,'lnP':np.log(P),'sqrtP':np.sqrt(P),'tP2':t*P**2,'t2P':t**2*P,'expt':np.exp(0.03*t),'Pexp':P*np.exp(-P),'sqrtt':np.sqrt(t),'lnt':np.log(t),'tlnP':t*np.log(P),'1/t':1/t,'P/t':P/t}
names=list(base)
def nmse(cols):
    B=np.c_[[base[c] for c in cols]].T
    cc=np.linalg.lstsq(B,dP_dt,rcond=None)[0]
    return np.sum((dP_dt-B@cc)**2)/np.sum((dP_dt-dP_dt.mean())**2)
res=[]
for k in [3,4,5]:
    for cols in itertools.combinations(names,k):
        if '1' not in cols: continue
        res.append((nmse(cols),cols))
res.sort(); 
for x in res[:8]: print(x)
